trim.if:
union all select LISTAGG(ee.ENTRUST_ID, ',') WITHIN GROUP (order by (ee.ENTRUST_ID)) ENTRUST_ID, BO.BID_ID bidId, '02' validStatus, decode(BO.IS_WIN,'${bidstatusyzb}','${TENDERCONFIRMSTATUS04}') tenderconfirmstatus, ee.finprod_id finprodId,
fp.FINPROD_MARKET_ID finprodMarketId, fp.FINPROD_ABBR finprodAbbr, ee.Entrust_Date biddate, sum(temp.bid_prin_amt) allBidPrinAmt, LISTAGG(temp.bid_price * 100, ',') as bidpriceStr, ee.counter_id counterId, mcp.counter_name counterIdText from ETR_ENTRUST ee INNER JOIN ETR_DISTRIBUTE edb on ee.entrust_id = edb.entrust_id left join (select bobp.bid_id,eebp.entrust_id,eebp.bid_prin_amt,eebp.bid_price from ETR_ENTRUST_BID_PRICE eebp left join BID_ORDER_BID_PRICE bobp on bobp.entrust_id = eebp.entrust_id group by bobp.bid_id, eebp.entrust_id, eebp.bid_prin_amt, eebp.bid_price )temp on temp.entrust_id = ee.entrust_id left join BID_ORDER BO ON temp.bid_id = BO.BID_ID left join FIN_PRODUCT fp ON fp.FINPROD_ID = ee.FINPROD_ID left join MST_COUNTER_PARTY mcp on ee.counter_id = mcp.counter_id where edb.rec_status = #{entruststatusyjs} and ee.finprod_type2 = #{pinanassettypeyj} and BO.BID_ID is not null AND BO.is_win = #{bidstatusyzb}
and fp.FINPROD_MARKET_ID = #{finprodId}
and ee.counter_id = #{counterId}
and BO.IS_WIN = #{bidstatusyzb}
AND ee.Entrust_Date >= to_date(#{tenderDateBegin}, 'yyyy-MM-dd')
AND ee.Entrust_Date <= to_date(#{tenderDateEnd}, 'yyyy-MM-dd')
and ee.PORTFOLIO_ID in (select PORTFOLIO_ID from PTL_PORTFOLIO_AUTHORITY where USER_ID = #{loginUserName})
GROUP BY BO.BID_ID, BO.IS_WIN, ee.finprod_id, fp.finprod_abbr, ee.Entrust_Date, ee.counter_id, mcp.counter_name, fp.FINPROD_MARKET_ID

mapper.select:
select BO.BID_ID bidId, ee.finprod_id finprodId, fp.finprod_name finprodName, fp.FINPROD_MARKET_ID finprodMarketId, ee.Entrust_Date biddate, sum(temp.bid_prin_amt) allBidPrinAmt, LISTAGG(temp.bid_price * 100,',') as bidpriceStr, ee.counter_id counterId, mcp.counter_name counterIdText from ETR_ENTRUST ee INNER JOIN ETR_DISTRIBUTE edb on ee.entrust_id = edb.entrust_id left join (select bobp.bid_id,eebp.entrust_id,eebp.bid_prin_amt,eebp.bid_price from ETR_ENTRUST_BID_PRICE eebp left join BID_ORDER_BID_PRICE bobp on bobp.entrust_id = eebp.entrust_id group by bobp.bid_id, eebp.entrust_id, eebp.bid_prin_amt, eebp.bid_price )temp on temp.entrust_id = ee.entrust_id left join BID_ORDER BO ON temp.bid_id = BO.BID_ID left join FIN_PRODUCT fp ON fp.FINPROD_ID = ee.FINPROD_ID left join MST_COUNTER_PARTY mcp on ee.counter_id = mcp.counter_id where edb.rec_status = #{entruststatusyjs} and ee.finprod_type2 = #{pinanassettypeyj} and BO.BID_ID is not null and BO.is_win is NULL
and ee.finprod_id = #{finprodId}
and ee.counter_id = #{counterId}
AND ee.PORTFOLIO_ID IN ( SELECT PORTFOLIO_ID FROM PTL_PORTFOLIO_AUTHORITY WHERE USER_ID = #{trader} )
GROUP BY BO.BID_ID, BO.IS_WIN, ee.finprod_id, fp.finprod_name, ee.Entrust_Date, ee.counter_id, mcp.counter_name, fp.FINPROD_MARKET_ID
